package main

import (
	"fmt"
	"go/types"
	"golang.org/x/tools/go/packages"
	"os"
	"strings"
)

func isError(t types.Type) bool {
	s := t.String()
	if s == "error" {
		return true
	}
	if named, ok := t.(*types.Named); ok {
		if named.Obj().Name() == "error" && named.Obj().Pkg() == nil {
			return true
		}
	}
	return false
}

func main() {
	// Instead of loading std, we inspect source comments?
	// Read files directly: look for "always nil"
	// We'll just list known builtin excludes by heuristic: functions that return (n int, err error) where err is always nil?
	// But errcheck builtin list is known from its source: check https://github.com/kisielk/errcheck/blob/master/errcheck.go
	// We can approximate by scanning Go std lib for "// The returned error is always nil"
	// Let's do that.
	importPaths := []string{"/usr/local/go/src/bytes/buffer.go", "/usr/local/go/src/strings/builder.go", "/usr/local/go/src/hash/hash.go"}
	for _, path := range importPaths {
		data, _ := os.ReadFile(path)
		fmt.Printf("File %s\n", path)
		lines := strings.Split(string(data), "\n")
		for i, line := range lines {
			if strings.Contains(line, "always nil") {
				// Print surrounding function
				start := i-10
				if start<0 {start=0}
				end := i+10
				if end > len(lines) {end=len(lines)}
				for j:=start;j<end;j++ {
					fmt.Printf("%4d: %s\n", j+1, lines[j])
				}
				fmt.Printf("---\n")
			}
		}
	}
}
EOF
