package main

import (
"fmt"
"go/ast"
"go/parser"
"go/token"
"os"
"path/filepath"
"strings"
)

func main(){
root:="/usr/local/go/src"
filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
 if err!=nil || info.IsDir() || !strings.HasSuffix(path,".go") {return nil}
 if strings.Contains(path,"/vendor/") {return nil}
 data,_:=os.ReadFile(path)
 txt:=string(data)
 if !strings.Contains(txt, "never returns an error") && !strings.Contains(strings.ToLower(txt), "always nil") && !strings.Contains(txt, "It never returns an error") { return nil }
 fset:=token.NewFileSet()
 f, err:=parser.ParseFile(fset, path, data, parser.ParseComments)
 if err!=nil {return nil}
 // Check for interface type with docs
 for _,decl:=range f.Decls{
  gen,ok:=decl.(*ast.GenDecl)
  if !ok || gen.Tok!=token.TYPE { continue }
  for _,spec:=range gen.Specs{
   ts,ok:=spec.(*ast.TypeSpec)
   if !ok {continue}
   iface,ok:=ts.Type.(*ast.InterfaceType)
   if !ok {continue}
   // Check methods
   if iface.Methods==nil {continue}
   for _,field:=range iface.Methods.List{
    if len(field.Names)==0 { // embedded?
     continue
    }
    doc:=field.Doc
    if doc==nil {continue}
    docText:=doc.Text()
    lower:=strings.ToLower(docText)
    if strings.Contains(lower,"never returns an error") || strings.Contains(lower,"always nil") {
     hasErr:=false
     // Check func type results
     if ft, ok:=field.Type.(*ast.FuncType); ok && ft.Results!=nil {
      for _,resField:=range ft.Results.List{
       start:=fset.Position(resField.Pos()).Offset
       end:=fset.Position(resField.End()).Offset
       typ:=string(data[start:end])
       if strings.Contains(typ,"error") { hasErr=true }
      }
     }
     if hasErr {
      fmt.Printf("%s interface %s method %s => doc %q\n", path, ts.Name.Name, field.Names[0].Name, strings.TrimSpace(docText))
     }
    }
   }
  }
 }
