 obj:=pkg2.Scope().Lookup(n)
 if tn,ok:=obj.(*types.TypeName);ok{
  named,_:=tn.Type().(*types.Named)
  if named==nil{continue}
  for _, tp:=range []types.Type{named, types.NewPointer(named)}{
   mset:=types.NewMethodSet(tp)
