package main

import (
"fmt"
"go/types"
"go/importer"
"os"
"os/exec"
"path/filepath"
"strings"
)

func main(){
 // Test which fmt funcs are builtin via error handling vs scan
 imp:=importer.Default()
 pkg,_:=imp.Import("fmt")
 for _, n:=range []string{"Print","Println","Printf","Fprint","Fprintf","Fprintln","Sprint","Sprintf","Errorf","Scan","Scanf","Sscan"}{
  obj:=pkg.Scope().Lookup(n)
  fn:=obj.(*types.Func)
  sig:=fn.Type().(*types.Signature)
  fmt.Printf("fmt.%s %s results: ", n, sig.String())
  for i:=0;i<sig.Results().Len();i++{ fmt.Printf("%s, ", sig.Results().At(i).Type().String()) }
  fmt.Printf("\n")
  // Check if error is always nil via our earlier brute: try to see if errcheck reports it
  dir,_:=os.MkdirTemp("/tmp","test")
  os.WriteFile(filepath.Join(dir,"go.mod"), []byte("module example.com/tmp\n\ngo 1.21\n"),0644)
  code:=fmt.Sprintf("import \"fmt\"\nfunc T(){fmt.%s(\"hi\")}", n)
  if n=="Fprint"||n=="Fprintln"||n=="Fprintf"{
   code=fmt.Sprintf("import \"fmt\"\nfunc T(){fmt.%s(nil, \"hi\")}", n)
  }
  if n=="Errorf"{
   code=`import "fmt"`+"\nfunc T(){fmt.Errorf(\"hi\")}"
  }
  if n=="Scan"||n=="Scanf"||n=="Sscan"{
   // need args
   if n=="Scan"{
    code=`import "fmt"`+"\nfunc T(){fmt.Scan(nil)}"
   } else if n=="Scanf"{
    code=`import "fmt"`+"\nfunc T(){fmt.Scanf(\"hi\", nil)}"
   } else {
    code=`import "fmt"`+"\nfunc T(){fmt.Sscan(\"hi\", nil)}"
   }
  }
  src:="package tmp\n"+code+"\n"
  os.WriteFile(filepath.Join(dir,"main.go"), []byte(src),0644)
  cmd:=exec.Command("/workspace/executable",".")
  cmd.Dir=dir
  out,_:=cmd.Output()
  hasDef:=strings.Contains(string(out),"main.go")
  cmd2:=exec.Command("/workspace/executable","-excludeonly",".")
  cmd2.Dir=dir
  out2,_:=cmd2.Output()
  hasExcl:=strings.Contains(string(out2),"main.go")
  status:="OTHER"
  if !hasDef && hasExcl {status="BUILTIN"}
  if hasDef && hasExcl {status="NOT_BUILTIN"}
  if !hasDef && !hasExcl {status="NOERR"}
  fmt.Printf("  => %s def %v excl %v\n", status, hasDef, hasExcl)
  os.RemoveAll(dir)
 }
}
EOF
