func (f *ignoreFlag) String() string { return strings.Join(*f, ",") }
func (f *ignoreFlag) Set(s string) error {
	// s is comma-separated list of pkg:regex
	parts := strings.Split(s, ",")
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p != "" {
			*f = append(*f, p)
		}
	}
	return nil
}

type tagsFlag []string

func (f *tagsFlag) String() string { return strings.Join(*f, ",") }
func (f *tagsFlag) Set(s string) error {
	// comma or space separated
	// Replace commas with spaces, then split by space
	s = strings.ReplaceAll(s, ",", " ")
	fields := strings.Fields(s)
	for _, field := range fields {
		field = strings.TrimSpace(field)
		if field != "" {
			*f = append(*f, field)
		}
	}
	return nil
