		var pkg, reg string
		if colon == -1 {
			// No colon, means regex applies to all packages
			pkg = ""
			reg = pat
		} else {
			pkg = pat[:colon]
			reg = pat[colon+1:]
		}
		// Compile regex
		re, err := regexp.Compile(reg)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: failed to check packages: err: invalid regex %q: %v\n", reg, err)
			os.Exit(2)
		}
		ignoreEntries = append(ignoreEntries, IgnoreEntry{Pkg: pkg, Regex: re, Raw: pat})
	}

	// Remaining args are package patterns
	patterns := flagSet.Args()
	if len(patterns) == 0 {
		patterns = []string{"."}
	}

	// Load packages via go list
	pkgs, err := loadPackages(patterns, tagsPatterns, mod)
	if err != nil {
		// loadPackages already printed error? It returns error with message to print
		fmt.Fprintf(os.Stderr, "%s\n", err.Error())
		os.Exit(2)
	}

	// Check for packages with Error
	hasLoadError := false
	for _, pkg := range pkgs {
		if pkg.Error != nil {
			hasLoadError = true
			// Format: error: failed to check packages: errors while loading package <ImportPath>: [-: <Err>]
			// For std not found, Err is "package nonexist is not in std ..."
			// For other errors, need to include Pos?
			// Use pkg.Error.Err
			// The observed format for nonexist: "error: failed to check packages: errors while loading package nonexist: [-: package nonexist is not in std (/usr/local/go/src/nonexist)]"
			// For bad syntax, it includes "# example.com/badproj" and file positions
			// But for go list errors, the Error.Err already contains that.
			// For go list, the package ImportPath may be the pattern, like "nonexist" or "./..."
			// The observed for pattern "./..." with no module gave: "error: failed to check packages: errors while loading package ./...: [-: pattern ./...: directory prefix . does not contain main module ...]"
			// So we can just use pkg.ImportPath as given, and pkg.Error.Err
			fmt.Fprintf(os.Stderr, "error: failed to check packages: errors while loading package %s: [-: %s]\n", pkg.ImportPath, pkg.Error.Err)
			if pkg.Error.Pos != "" {
				// Sometimes Pos is set? For nonexist, Pos is empty
			}
		}
	}
	if hasLoadError {
		os.Exit(2)
	}

	// Now for each package, check for unchecked errors
	cwd, _ := os.Getwd()
	var allUnckecked []UncheckedError
	var loadErrors []string // for type checking errors

	for _, pkg := range pkgs {
		// Verbose logging
		if verbose {
			fmt.Fprintf(os.Stderr, "checking %s\n", pkg.ImportPath)
		}
		// Check if package should be ignored via ignorePkg or ignore
		// But ignorePkg and ignore are per-function, not per-package. However if ignorePkg contains the package's import path, then all functions in that package are ignored, so we can skip checking? But we still need to check? Actually if package is in ignorePkg, then no errors should be reported for that package, so we can skip.
		// But we saw earlier that with -ignorepkg, the package's errors were still partially reported? For single package with -ignorepkg fmt, the fmt.Println was still not reported? Wait we tested with single package that imports fmt and has fmt.Println, with -ignorepkg fmt, the output was still not reported (since fmt.Println is builtin). Hmm.
		// For package that is itself ignored (like -ignorepkg example.com/tmp), then no errors should be reported for that package's own functions (like foo). We saw earlier that with -ignorepkg example.com/tmp and code foo() in same package, it was ignored (no report). So we can skip package if its ImportPath is in ignorePkgList.
		shouldSkipPackage := false
		for _, ignPkg := range ignorePkgList {
			if ignPkg == pkg.ImportPath {
				shouldSkipPackage = true
				break
			}
		}
		if shouldSkipPackage {
			continue
		}

		// Collect files for this package
		// Determine which files to include based on flags
		// Use GoFiles always, plus TestGoFiles and XTestGoFiles if not ignoretests
		// But go list's GoFiles already excludes ignored files based on tags, but includes regular files
		// We should use pkg.GoFiles for main files
		// For test files, we need to handle
		// For simplicity, we will use pkg.GoFiles + (if !ignoreTests then pkg.TestGoFiles + pkg.XTestGoFiles)
		// However XTestGoFiles are for external tests, we will handle separately

		// For now, handle main files
		filesToParse := []string{}
		filesToParse = append(filesToParse, pkg.GoFiles...)
		if !ignoreTests {
			filesToParse = append(filesToParse, pkg.TestGoFiles...)
			// For XTestGoFiles, they are package pkg_test, we could handle as separate package, but for now include them as well? They have different package name, but we can still parse them as part of same package? Might cause package name mismatch, but we can handle.
			// Let's also include XTestGoFiles but need to handle package name difference: they are "package pkg_test", so type checking with same import path would fail.
			// So we will handle XTestGoFiles separately as external test package
		}

		// For each file, check if generated and should be ignored
		// We need to parse files to check IsGenerated

		// Build list of *ast.File and file paths
		fset := token.NewFileSet()
		var astFiles []*ast.File
		var filePaths []string
		var fileContents [][]byte

		for _, fname := range filesToParse {
			fpath := filepath.Join(pkg.Dir, fname)
			// Read file content for line text later
			content, err := os.ReadFile(fpath)
			if err != nil {
				// Could not read file, treat as load error?
				continue
			}
			// Parse
			f, err := parser.ParseFile(fset, fpath, content, parser.ParseComments)
			if err != nil {
				// If parser error, we will still have file but with errors
				// We should still add file to astFiles, but type checking will report errors
				// For now, if f is nil, create empty?
				if f == nil {
					// Create dummy file for error reporting? We'll still need to report the parse error via types.Config
					// Instead, we can just add file as is; parser may have returned partial
					continue
				}
			}
			if f != nil && ignoreGenerated && ast.IsGenerated(f) {
				continue
			}
			astFiles = append(astFiles, f)
			filePaths = append(filePaths, fpath)
			fileContents = append(fileContents, content)
		}

		// Also handle XTestGoFiles if not ignoretests
		if !ignoreTests && len(pkg.XTestGoFiles) > 0 {
			// For XTest, create separate package check
			// We'll handle after main package
			xtestFset := token.NewFileSet()
			var xtestFiles []*ast.File
			for _, fname := range pkg.XTestGoFiles {
				fpath := filepath.Join(pkg.Dir, fname)
				content, err := os.ReadFile(fpath)
				if err != nil {
					continue
				}
				f, err := parser.ParseFile(xtestFset, fpath, content, parser.ParseComments)
				if err != nil && f == nil {
					continue
				}
				if f != nil && ignoreGenerated && ast.IsGenerated(f) {
					continue
				}
				xtestFiles = append(xtestFiles, f)
			}
			if len(xtestFiles) > 0 {
				// Type check external test package
				// Its import path is pkg.ImportPath + "_test"
				xtestImportPath := pkg.ImportPath + "_test"
				// Check it
				errors, unchecked := checkPackageFiles(xtestImportPath, pkg.Dir, xtestFiles, xtestFset, excludes, excludeOnly, ignoreEntries, ignorePkgList, cwd, abspath, verbose)
				if len(errors) > 0 {
					for _, e := range errors {
						loadErrors = append(loadErrors, fmt.Sprintf("error: failed to check packages: errors while loading package %s: [-: # %s\n%s]", xtestImportPath, xtestImportPath, e))
					}
				} else {
					allUnckecked = append(allUnckecked, unchecked...)
				}
			}
		}

		if len(astFiles) == 0 {
			continue
		}

		// Type check
		errors, unchecked := checkPackageFiles(pkg.ImportPath, pkg.Dir, astFiles, fset, excludes, excludeOnly, ignoreEntries, ignorePkgList, cwd, abspath, verbose)
		if len(errors) > 0 {
			for _, e := range errors {
				loadErrors = append(loadErrors, fmt.Sprintf("error: failed to check packages: errors while loading package %s: [-: # %s\n%s]", pkg.ImportPath, pkg.ImportPath, e))
			}
		} else {
			allUnckecked = append(allUnckecked, unchecked...)
		}
	}

	// If any load errors from type checking, print them and exit 2
	if len(loadErrors) > 0 {
		for _, e := range loadErrors {
			fmt.Fprintln(os.Stderr, e)
		}
		os.Exit(2)
	}

	// Sort unchecked errors by filename, line, col
	sort.Slice(allUnckecked, func(i, j int) bool {
		if allUnckecked[i].Filename != allUnckecked[j].Filename {
			return allUnckecked[i].Filename < allUnckecked[j].Filename
		}
		if allUnckecked[i].Line != allUnckecked[j].Line {
			return allUnckecked[i].Line < allUnckecked[j].Line
		}
		return allUnckecked[i].Col < allUnckecked[j].Col
	})

	// Print unchecked errors to stdout
	for _, ue := range allUnckecked {
		// Format: filename:line:col: \t funcName \t lineText  OR  filename:line:col: \t lineText
		// For verbose, include funcName if non-empty
		// For abspath, filename is already absolute, else relative
		var out string
		if verbose && ue.FuncName != "" {
			out = fmt.Sprintf("%s:%d:%d:\t%s\t%s", ue.Filename, ue.Line, ue.Col, ue.FuncName, ue.LineText)
		} else {
			out = fmt.Sprintf("%s:%d:%d:\t%s", ue.Filename, ue.Line, ue.Col, ue.LineText)
		}
		fmt.Fprintln(os.Stdout, out)
	}

	if len(allUnckecked) > 0 {
		os.Exit(1)
	}
	os.Exit(0)
}

type UncheckedError struct {
	Filename string
	Line     int
	Col      int
	FuncName string
	LineText string
	Pos      token.Position
}

func parseExcludeFile(content string) []ExcludeEntry {
	var entries []ExcludeEntry
	lines := strings.Split(content, "\n")
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "//") {
			continue
		}
		// Check for suffix (TYPE)
		// If line ends with ) and contains (, try to extract
		// But need to avoid mis-parsing (*pkg.Type).Method
		// That line ends with not ), it ends with Method, so no suffix
		// For io.Copy(*bytes.Buffer), it ends with ), and contains "("
		if strings.HasSuffix(line, ")") && strings.Contains(line, "(") {
			idx := strings.LastIndex(line, "(")
			if idx != -1 {
				funcPart := strings.TrimSpace(line[:idx])
				typePart := strings.TrimSpace(line[idx+1 : len(line)-1])
				// Heuristic: funcPart should contain "." and typePart should look like a type (contains letters, maybe * or / or .)
				// If funcPart is like "io.Copy", it's valid
				// If funcPart is like "(*net/http.Client).Do", it would have been "(*net/http.Client).Do" with no suffix, but it doesn't end with ), so not here
				// So we can treat as suffix if funcPart contains "."
				if strings.Contains(funcPart, ".") {
					entries = append(entries, ExcludeEntry{Func: funcPart, Type: typePart})
					continue
				}
			}
		}
		entries = append(entries, ExcludeEntry{Func: line, Type: ""})
	}
	return entries
}

func loadPackages(patterns []string, tags []string, mod string) ([]*GoListPackage, error) {
	args := []string{"list", "-e", "-json"}
	if len(tags) > 0 {
		args = append(args, "-tags", strings.Join(tags, ","))
	}
	if mod != "" {
		args = append(args, "-mod", mod)
	}
	args = append(args, patterns...)
	cmd := exec.Command("go", args...)
	// Use current env, but need to ensure GO111MODULE etc? Just use default
	var stdout bytes.Buffer
	var stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()
	if err != nil {
		// If go list failed, return error with stderr
		// The observed error for invalid mod: "error: failed to check packages: err: exit status 1: stderr: -mod=invalid not supported ..."
		// So we should return that formatted
		// The error from exec is like exit status 1, and stderr contains the message
		return nil, fmt.Errorf("error: failed to check packages: err: %v: stderr: %s", err, stderr.String())
	}
	// Parse stdout as stream of JSON objects
	dec := json.NewDecoder(&stdout)
	var pkgs []*GoListPackage
	for {
		var pkg GoListPackage
		if err := dec.Decode(&pkg); err != nil {
			if err.Error() == "EOF" {
				break
			}
			// If decode error, break
			break
		}
		pkgs = append(pkgs, &pkg)
	}
	// If no packages and stderr not empty, maybe error?
	if len(pkgs) == 0 && stderr.Len() > 0 {
		return nil, fmt.Errorf("error: failed to check packages: err: %s", stderr.String())
	}
	return pkgs, nil
}

