func returnsError(call *ast.CallExpr, info *types.Info) bool {
	// Get type of call
	tv, ok := info.Types[call]
	if !ok {
		return false
	}
	typ := tv.Type
	if typ == nil {
		return false
	}
	// If typ is *types.Tuple, check last element
	if tuple, ok := typ.(*types.Tuple); ok {
		if tuple.Len() == 0 {
			return false
		}
		last := tuple.At(tuple.Len() - 1).Type()
		return isErrorType(last)
	}
	// If single value, check if it's error
	return isErrorType(typ)
}

func isErrorType(t types.Type) bool {
	if t == nil {
		return false
	}
	// Check if t is error interface
	// Use String() == "error" or named error
	if t.String() == "error" {
		return true
	}
	if named, ok := t.(*types.Named); ok {
		if named.Obj().Name() == "error" && named.Obj().Pkg() == nil {
			return true
		}
	}
	// Also check for *types.Interface that is error? But error is interface, but String() will be "error"
	return false
}

func getSignature(call *ast.CallExpr, info *types.Info) *types.Signature {
	// Try to get object for Fun
	switch fun := call.Fun.(type) {
	case *ast.Ident:
		obj := info.ObjectOf(fun)
		if fn, ok := obj.(*types.Func); ok {
			if sig, ok := fn.Type().(*types.Signature); ok {
				return sig
			}
		}
		// Also could be var of func type
		if tv, ok := info.Types[fun]; ok {
			if sig, ok := tv.Type.(*types.Signature); ok {
				return sig
			}
		}
	case *ast.SelectorExpr:
		// Check Selections
		if sel, ok := info.Selections[fun]; ok {
			if fn, ok := sel.Obj().(*types.Func); ok {
				if sig, ok := fn.Type().(*types.Signature); ok {
					return sig
				}
			}
		}
		// Also check Uses for Sel
		if obj := info.ObjectOf(fun.Sel); obj != nil {
			if fn, ok := obj.(*types.Func); ok {
				if sig, ok := fn.Type().(*types.Signature); ok {
					return sig
				}
			}
		}
		// For qualified func like fmt.Println, the Sel's object is the func
		// For method call like b.Write, the Sel's object is the method
	}
	// Fallback: try to get type of call's Fun as signature
	if tv, ok := info.Types[call.Fun]; ok {
		if sig, ok := tv.Type.(*types.Signature); ok {
			return sig
		}
	}
	return nil
}

func getFuncName(call *ast.CallExpr, info *types.Info, currentPkg string) string {
	// Get the called function object
	var obj types.Object
	var sig *types.Signature
	switch fun := call.Fun.(type) {
	case *ast.Ident:
		obj = info.ObjectOf(fun)
		if fn, ok := obj.(*types.Func); ok {
			sig = fn.Type().(*types.Signature)
		}
	case *ast.SelectorExpr:
		if sel, ok := info.Selections[fun]; ok {
			obj = sel.Obj()
			if fn, ok := obj.(*types.Func); ok {
				sig = fn.Type().(*types.Signature)
			}
		} else {
			obj = info.ObjectOf(fun.Sel)
			if fn, ok := obj.(*types.Func); ok {
				sig = fn.Type().(*types.Signature)
			}
		}
	}
	if obj == nil {
		return ""
	}
	fn, ok := obj.(*types.Func)
	if !ok {
		return ""
	}
	if sig == nil {
		if s, ok := fn.Type().(*types.Signature); ok {
			sig = s
		} else {
			return ""
		}
	}
	pkgPath := ""
	if fn.Pkg() != nil {
		pkgPath = fn.Pkg().Path()
	}
	name := fn.Name()
	recv := sig.Recv()
	if recv != nil {
		recvType := recv.Type().String()
		// For verbose, they show like "(*os.File).Close" or "(bytes.Buffer).Write" etc.
		// recvType already includes package, like "*bytes.Buffer" or "bytes.Buffer"
		// But for methods on generic types, it may be "*example.com/tmp.T"
		return fmt.Sprintf("(%s).%s", recvType, name)
	} else {
		// For package-level func, if it's from current package and not method, don't show? As per observed, local funcs don't show
		if pkgPath == currentPkg {
			return ""
		}
		if pkgPath == "" {
			return name
		}
		return fmt.Sprintf("%s.%s", pkgPath, name)
	}
}

func isExcluded(call *ast.CallExpr, info *types.Info, file *ast.File, currentPkg string, excludes []ExcludeEntry, excludeOnly bool, ignoreEntries []struct {
	Pkg   string
	Regex *regexp.Regexp
	Raw   string
}, ignorePkgList []string) bool {
	// Get func object and signature
	var obj types.Object
	var sig *types.Signature
	switch fun := call.Fun.(type) {
	case *ast.Ident:
		obj = info.ObjectOf(fun)
	case *ast.SelectorExpr:
		if sel, ok := info.Selections[fun]; ok {
			obj = sel.Obj()
		} else {
			obj = info.ObjectOf(fun.Sel)
		}
	}
	if obj == nil {
		return false
	}
	fn, ok := obj.(*types.Func)
	if !ok {
		return false
	}
	if fn.Pkg() == nil {
		return false
	}
	pkgPath := fn.Pkg().Path()
	funcName := fn.Name()
	// Check ignorePkg
	for _, ignPkg := range ignorePkgList {
		if ignPkg == pkgPath {
			return true
		}
	}
	// Check ignore patterns
	for _, entry := range ignoreEntries {
		if entry.Pkg != "" && entry.Pkg != pkgPath {
			continue
		}
		if entry.Regex.MatchString(funcName) {
			return true
		}
	}
	// Check builtin excludes (if not excludeOnly)
	if !excludeOnly {
		if isBuiltinExclude(pkgPath, funcName, sig) {
			return true
		}
	}
	// Check exclude file
	// Need to get qualified name for matching
	qualified := ""
	recv := sig.Recv()
	if recv != nil {
		recvType := recv.Type().String()
		qualified = fmt.Sprintf("(%s).%s", recvType, funcName)
	} else {
		qualified = fmt.Sprintf("%s.%s", pkgPath, funcName)
	}
	// Also for methods, the exclude file may use form like "(*pkg.Type).Method" – our qualified already does that
	// For package func, it's "pkg.Func"
	// Now check each exclude entry
	for _, ex := range excludes {
		if ex.Func != qualified {
			// Also need to handle that exclude file may have "pkg.Func" without receiver, but our qualified for method includes receiver, so not match
			// For method, ex.Func would be like "(*bytes.Buffer).Write" – our qualified is "(*bytes.Buffer).Write" – matches
			// For package func, ex.Func is "fmt.Println" – our qualified is "fmt.Println" – matches
			continue
		}
		if ex.Type == "" {
			return true
		}
		// Need to check first arg type
		if len(call.Args) == 0 {
			continue
		}
		firstArg := call.Args[0]
		// Special handling for os.Stdout / os.Stderr
		if ex.Type == "os.Stdout" || ex.Type == "os.Stderr" {
			// Check if first arg is selector os.Stdout
			if sel, ok := firstArg.(*ast.SelectorExpr); ok {
				if ident, ok := sel.X.(*ast.Ident); ok && ident.Name == "os" {
					if sel.Sel.Name == "Stdout" && ex.Type == "os.Stdout" {
						return true
					}
					if sel.Sel.Name == "Stderr" && ex.Type == "os.Stderr" {
						return true
					}
				}
			}
			continue
		}
		// Otherwise, check type of first arg
		tv, ok := info.Types[firstArg]
		if !ok {
			continue
		}
		argTypeStr := tv.Type.String()
		// For type string, need to handle that it may be " *bytes.Buffer" with package prefix? The exclude file's type is like "*bytes.Buffer"
		// Our argTypeStr will be "*bytes.Buffer" (with package), matches
		if argTypeStr == ex.Type {
			return true
		}
		// Also handle that argType may be "bytes.Buffer" vs "*bytes.Buffer" with pointer?
		// For &b where b is bytes.Buffer, type is *bytes.Buffer, matches
		// For b where b is bytes.Buffer, type is bytes.Buffer, not *bytes.Buffer, so not match
	}
	return false
}

func isBuiltinExclude(pkgPath, funcName string, sig *types.Signature) bool {
	if sig == nil {
		return false
	}
	// Check if function returns error and is known builtin
	// We will hardcode list
	// For fmt
	if pkgPath == "fmt" {
		if funcName == "Print" || funcName == "Println" || funcName == "Printf" {
			return true
		}
	}
	// For bytes.Buffer
	if pkgPath == "bytes" {
		recv := sig.Recv()
		if recv != nil {
			recvStr := recv.Type().String()
			// recvStr is like "*bytes.Buffer" or "bytes.Buffer"
			if strings.Contains(recvStr, "Buffer") {
				if funcName == "Write" || funcName == "WriteString" || funcName == "WriteByte" || funcName == "WriteRune" {
					return true
				}
			}
		}
	}
	// For strings.Builder
	if pkgPath == "strings" {
		recv := sig.Recv()
		if recv != nil {
			recvStr := recv.Type().String()
			if strings.Contains(recvStr, "Builder") {
				if funcName == "Write" || funcName == "WriteString" || funcName == "WriteByte" || funcName == "WriteRune" {
					return true
				}
			}
		}
	}
	// For hash
	if pkgPath == "hash" {
		recv := sig.Recv()
		if recv != nil {
			recvStr := recv.Type().String()
			if strings.Contains(recvStr, "Hash") && funcName == "Write" {
				return true
			}
		}
	}
	if pkgPath == "hash/maphash" {
		recv := sig.Recv()
		if recv != nil {
			recvStr := recv.Type().String()
			if strings.Contains(recvStr, "Hash") {
				if funcName == "Write" || funcName == "WriteString" || funcName == "WriteByte" {
					return true
				}
			}
		}
	}
	// For hash implementations (crypto, hash/*)
	if (strings.HasPrefix(pkgPath, "hash/") || strings.HasPrefix(pkgPath, "crypto/")) && funcName == "Write" {
		// Check if recv type contains "digest" or similar, but for now assume any Write in those pkgs is builtin if it returns (int, error)
		// We saw that Write in those pkgs was builtin
		return true
	}
	// Also for io.Pipe CloseWithError? Not needed
	return false
}
EOF
"}

