  mset:=types.NewMethodSet(tp)
  for i:=0;i<mset.Len();i++{
   fn:=mset.At(i).Obj().(*types.Func)
   sig:=fn.Type().(*types.Signature)
   if !hasError(sig){continue}
   fmt.Printf("%s %s %s\n", tp.String(), fn.Name(), sig.String())
   if fn.Name()=="Write"{
